        int newCap = Math.max(bytes.length * 2, required);
        // Allocate a new array and copy the existing data
        byte[] newBytes = new byte[newCap];
        System.arraycopy(bytes, 0, newBytes, 0, len);
        // Update the reference to point to the new buffer
        bytes = newBytes;
    }
}

private void enlarge(final int size) {
    // Validate the requested additional size.
    if (size <= 0) {
        throw new IllegalArgumentException("size must be positive");
    }

    // Current capacity (may be 0 if no array has been allocated yet).
    int currentCapacity = (bytes != null) ? bytes.length : 0;

    // New capacity must be large enough to hold the requested additional bytes.
    long newCapacityLong = (long) currentCapacity + size;
    if (newCapacityLong > Integer.MAX_VALUE) {
        // Avoid integer overflow – suggest resizing in blocks.
        throw new OutOfMemoryError("Requested byte vector size too large");
    }
    int newCapacity = (int) newCapacityLong;

    // Allocate new array and copy the existing data.
    byte[] newArray = new byte[newCapacity];
    if (currentCapacity > 0) {
        System.arraycopy(bytes, 0, newArray, 0, currentCapacity);
    }

    // Replace the old array with the enlarged one.
    bytes = newArray;
}

