private TreeNode<T> rotateRight(TreeNode<T> node){
    // If the node is null or has no left child, rotation cannot be performed
    if (node == null || node.left == null) {
        return node;
    }

    // Perform rotation
    TreeNode<T> newRoot = node.left;
    node.left = newRoot.right;
    newRoot.right = node;

    // Return the new root after rotation
    return newRoot;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Guard against null node or missing left child (rotation not possible)
    if (node == null || node.left == null) {
        return node;
    }

    // The left child will become the new root of this subtree
    TreeNode<T> leftChild = node.left;

    // Reattach the right subtree of leftChild as the left subtree of node
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    // Place node as the right child of its former left child
    leftChild.right = node;

    // Update parent pointers
    leftChild.parent = node.parent;
    node.parent = leftChild;

    // Return the new root of this subtree
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    // If node is null or has no left child, rotation cannot be performed
    if (node == null || node.left == null) {
        return node;
    }

    TreeNode<T> leftChild = node.left;
    TreeNode<T> leftRight = leftChild.right;

    // Perform the rotation
    leftChild.right = node;
    node.left = leftRight;

    // Update parent references
    leftChild.parent = node.parent;
    node.parent = leftChild;
    if (leftRight != null) {
        leftRight.parent = node;
    }

    // Update the reference from the original parent to point to the new root
    if (leftChild.parent != null) {
        if (leftChild.parent.left == node) {
            leftChild.parent.left = leftChild;
        } else if (leftChild.parent.right == node) {
            leftChild.parent.right = leftChild;
        }
    }

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> leftChild = node.left;
    TreeNode<T> temp = leftChild.right;

    leftChild.right = node;
    node.left = temp;

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> left = node.left;
    node.left = left.right;
    left.right = node;
    return left;
}

