public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    // Assume the enclosing class has a field named 'conversionPattern'.
    String pattern = this.conversionPattern;
    if (pattern == null) {
        // Fallback: return the message if no pattern is defined.
        return event.getMessage() == null ? "" : event.getMessage().toString();
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < pattern.length(); i++) {
        char ch = pattern.charAt(i);
        if (ch == '%' && i + 1 < pattern.length()) {
            char spec = pattern.charAt(++i);
            switch (spec) {
                case 'd':
                    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
                    sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
                    break;
                case 'p':
                    sb.append(event.getLevel() != null ? event.getLevel().toString() : "");
                    break;
                case 'c':
                    sb.append(event.getLoggerName() != null ? event.getLoggerName() : "");
                    break;
                case 't':
                    sb.append(event.getThreadName() != null ? event.getThreadName() : "");
                    break;
                case 'm':
                    sb.append(event.getMessage() != null ? event.getMessage().toString() : "");
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    break;
                case '%':
                    sb.append('%');
                    break;
                default:
                    // Unrecognized specifier, output literally
                    sb.append('%').append(spec);
                    break;
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

