    }
    try {
        // Create a new mapping. The constructor that accepts source and target graphs
        // is used when available; otherwise fall back to the no-arg constructor.
        IsomorphicGraphMapping<V,E> mapping;
        try {
            mapping = new IsomorphicGraphMapping<>(graph, graph);
        } catch (NoSuchMethodError | UnsupportedOperationException e) {
            mapping = new IsomorphicGraphMapping<>();
        }
        // Map each vertex and edge onto itself
        for (V vertex : graph.vertexSet()) {
            mapping.addCorrespondence(vertex, vertex);
        }
        for (E edge : graph.edgeSet()) {
            mapping.addCorrespondence(edge, edge);
        }
        return mapping;
    } catch (Exception ex) {
        throw new RuntimeException("Failed to create identity mapping", ex);
    }
