public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return; // nothing to delete
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (!file.exists()) {
        // Nothing to schedule, no error.
        return;
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
        // After scheduling children, schedule the directory itself.
    }
    try {
        file.deleteOnExit();
    } catch (SecurityException se) {
        throw new IOException("Permission denied to schedule deleteOnExit for " + file, se);
    } catch (Exception e) {
        throw new IOException("Failed to schedule deleteOnExit for " + file, e);
    }
}

