        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    try {
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Could not register file for deletion on exit: " + file, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        throw new java.io.FileNotFoundException("File does not exist: " + file);
    }
    try {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children != null) { // null means an I/O error or permission issue
                for (File child : children) {
                    forceDeleteOnExit(child);
                }
            }
        }
        file.deleteOnExit();
    } catch (SecurityException se) {
        throw new IOException("Unable to schedule delete on exit for file: " + file, se);
    }
}

