    int leftCount = 2;
    int rightCount = 2;

    java.util.List<V> leftVertices = new java.util.ArrayList<>();
    java.util.List<V> rightVertices = new java.util.ArrayList<>();

    try {
        // Add left partition vertices
        for (int i = 0; i < leftCount; i++) {
            @SuppressWarnings("unchecked")
            V v = (V)(String) ("L" + i);
            if (target.addVertex(v)) {
                leftVertices.add(v);
                resultMap.put("L" + i, v);
            } else {
                // vertex already present, still record it
                leftVertices.add(v);
                resultMap.putIfAbsent("L" + i, v);
            }
        }

        // Add right partition vertices
        for (int i = 0; i < rightCount; i++) {
            @SuppressWarnings("unchecked")
            V v = (V)(String) ("R" + i);
            if (target.addVertex(v)) {
                rightVertices.add(v);
                resultMap.put("R" + i, v);
            } else {
                rightVertices.add(v);
                resultMap.putIfAbsent("R" + i, v);
            }
        }

        // Create all edges between left and right partitions
        for (V lv : leftVertices) {
            for (V rv : rightVertices) {
                try {
                    target.addEdge(lv, rv);
                } catch (Exception e) {
                    // Ignore duplicate edges or other graph-specific exceptions
                }
            }
        }
    } catch (Exception e) {
        // Wrap unexpected issues in a runtime exception for caller visibility
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

