        throw new IllegalArgumentException("Target graph and resultMap must not be null");
    }

    List<V> leftSet  = new ArrayList<>();
    List<V> rightSet = new ArrayList<>();

    // Separate vertices into two partitions based on key prefixes ("U"/"u" and "V"/"v")
    for (Map.Entry<String, V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        if (key != null && (key.startsWith("U") || key.startsWith("u"))){
            leftSet.add(entry.getValue());
        } else if (key != null && (key.startsWith("V") || key.startsWith("v"))){
            rightSet.add(entry.getValue());
        }
    }

    // Ensure all vertices from resultMap are present in the target graph
    for (V vertex : resultMap.values()){
        if (!target.containsVertex(vertex)){
            target.addVertex(vertex);
        }
    }

    // Add edges between every vertex in leftSet and every vertex in rightSet
    for (V u : leftSet){
        for (V v : rightSet){
            target.addEdge(u, v);
        }
    }
}

