public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // This method constructs a simple complete bipartite graph K_{3,3}
    // using string vertex identifiers. The vertices are added to the
    // resultMap so callers can reference them later.
    // In case the graph type does not allow adding new vertices or
    // edges, the method will throw a RuntimeException wrapping the
    // original exception.

    try {
        // Prepare two partitions of vertices
        List<V> leftPartition = new ArrayList<>();
        List<V> rightPartition = new ArrayList<>();

        // Create 3 vertices in each partition
        for (int i = 1; i <= 3; i++) {
            String vertexName = "A" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) vertexName; // cast to generic type
            target.addVertex(vertex);
            resultMap.put(vertexName, vertex);
            leftPartition.add(vertex);
        }
        for (int i = 1; i <= 3; i++) {
            String vertexName = "B" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) vertexName;
            target.addVertex(vertex);
            resultMap.put(vertexName, vertex);
            rightPartition.add(vertex);
        }

        // Add edges to make the graph complete bipartite:
        // connect every vertex in the left partition with every vertex in the right partition
        for (V leftVertex : leftPartition) {
            for (V rightVertex : rightPartition) {
                // Only add the edge if it does not already exist
                if (!target.containsEdge(leftVertex, rightVertex)) {
                    target.addEdge(leftVertex, rightVertex);
                }
            }
        }
