public String toString() {
    // If a dedicated StringBuilder instance is used for accumulating characters,
    // return its string representation. Otherwise fall back to a simple string
    // representation of this object.
    try {
        if (this.builder != null) {
            return this.builder.toString();
        }
    } catch (Exception ignored) {
        // ignore any exception while accessing the builder
    }
    // Fallback: use the default implementation (generally the class name and hashcode)
    return super.toString();
}

