protected void subAppend(LoggingEvent event) {
    if (event == null) {
        return;
    }
    try {
        String msg = (layout != null) ? layout.format(event) : event.toString();
        if (writer != null) {
            writer.write(msg);
            writer.flush();
        } else if (outputStream != null) {
            outputStream.write(msg.getBytes("UTF-8"));
            outputStream.flush();
        } else {
            System.out.print(msg);
        }
    } catch (java.io.IOException e) {
        if (errorHandler != null) {
            errorHandler.error("Failed to write event", e, 0);
        } else {
            System.err.println("Failed to write event: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

protected void subAppend(LoggingEvent event){
    if (event == null) {
        return;
    }
    try {
        Object msgObj = event.getMessage();
        String msg = msgObj != null ? msgObj.toString() : "null";
        String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
        java.util.Date time = new java.util.Date(event.getTimeStamp());
        System.out.println(time + " [" + level + "] " + msg);
    } catch (Exception e) {
        System.err.println("Error while writing log event: " + e);
    }
}

protected void subAppend(LoggingEvent event){
    if (event == null) {
        // No event to process; simply return
        return;
    }
    try {
        // Retrieve the formatted log message from the event
        String message = event.getFormattedMessage();
        if (message == null) {
            message = "";
        }
        // Perform the actual write operation (here we write to standard output)
        System.out.println(message);
    } catch (Exception ex) {
        // If any runtime exception occurs during writing, print it to standard error
        System.err.println("Error while writing log event: " + ex.getMessage());
        ex.printStackTrace(System.err);
    }
}

int addType(final String value) {
    if (value == null) {
        throw new IllegalArgumentException("type value cannot be null");
    }
    /* Ensure the type table exists */
    if (typeTable == null) {
        typeTable = new java.util.ArrayList<>();
    }
    /* Look for an existing type with the same value */
    for (int i = 0; i < typeTable.size(); i++) {
        Symbol sym = typeTable.get(i);
        if (sym != null) {
            // Most Symbol implementations expose the stored value via a getValue() or getName() method.
            try {
                String storedValue = sym.getValue(); // or sym.getName()
                if (value.equals(storedValue)) {
                    return i; // already exists
                }
            } catch (NoSuchMethodError | SecurityException | IllegalAccessException | java.lang.reflect.InvocationTargetException |
                     IllegalArgumentException e) {
                /* If getValue() is not available or cannot be accessed, fall back to toString()
                   comparison as a last resort. */
                if (value.equals(sym.toString())) {
                    return i;
                }
            }
        }
    }
    /* No existing type found – add a new Symbol */
    Symbol newSym = new Symbol(value);
    int newIndex = typeTable.size();
    typeTable.add(newSym);
    return newIndex;
}

