public void accept(final METRICS data) {
    // Disallow null values
    if (data == null) {
        return;
    }
    try {
        // Store (or replace) the metric value in the cache.
        // No concurrency protection is provided, so we safely put the
        // new value, overriding any previous entry for the same key.
        cache.put(data, data);
    } catch (Exception ex) {
        // If the cache operation fails, the exception is swallowed to
        // avoid propagating unchecked errors.  Depending on the
        // surrounding infrastructure, a proper logging mechanism
        // could be inserted here.
    }
}

