@Override
public int available() throws IOException {
    try {
        // In a common FilterInputStream implementation, the wrapped stream is held
        // in the protected field 'in'. If it is null, there is nothing available.
        if (in == null) {
            return 0;
        }
        return in.available();
    } catch (IOException e) {
        // Propagate IOException unchanged.
        throw e;
    } catch (Exception e) {
        // Wrap any unexpected exception into an IOException.
        throw new IOException("Failed to get available bytes", e);
    }
}

@Override public int available() throws IOException {
    // Return the number of bytes that can be read without blocking.
    // As this stream does not have any buffered data or underlying source,
    // we report that no bytes can be read immediately.
    return 0;
}

@Override public int available() throws IOException {
    return 0;
}

@Override
public int available() throws IOException {
    try {
        if (in == null) {
            throw new IOException("Stream closed");
        }
        int avail = in.available();
        return avail >= 0 ? avail : 0;
    } catch (IOException e) {
        throw e;
    } catch (RuntimeException e) {
        throw new IOException("Error determining available bytes", e);
    }
}

@Override public int available() throws IOException {
    if (in == null) {
        throw new IOException("Underlying input stream is null");
    }
    return in.available();
}

public Mappings diffStructure(String tableName,Mappings mappings){
    if (mappings == null) {
        return null;
    }
    try {
        // Attempt to obtain the underlying Map from the Mappings instance via reflection.
        java.lang.reflect.Method getMappingMethod = null;
        for (java.lang.reflect.Method m : mappings.getClass().getMethods()) {
            if (m.getName().equals("getMapping") && m.getParameterCount() == 0) {
                getMappingMethod = m;
                break;
            }
        }
        if (getMappingMethod == null) {
            // If there is no getMapping method, just return the original mapping.
            return mappings;
        }
        Object mapObj = getMappingMethod.invoke(mappings);
        if (!(mapObj instanceof java.util.Map)) {
            return mappings;
        }
        @SuppressWarnings("unchecked")
        java.util.Map<String, Object> currentMap = new java.util.HashMap<>((java.util.Map<String, Object>) mapObj);

        // Remove the _source entry if present to avoid update conflicts.
        currentMap.remove("_source");

        // Construct a new Mappings object containing only the filtered map.
        Mappings result;
        try {
            // Try to use a constructor that accepts a Map.
            java.lang.reflect.Constructor<?> ctor = mappings.getClass().getConstructor(java.util.Map.class);
            result = (Mappings) ctor.newInstance(currentMap);
        } catch (Throwable t) {
            // Fall back to default constructor + setter.
            result = (Mappings) mappings.getClass().newInstance();
            java.lang.reflect.Method setMappingMethod = null;
            for (java.lang.reflect.Method m : mappings.getClass().getMethods()) {
                if (m.getName().equals("setMapping") && m.getParameterCount() == 1
                        && java.util.Map.class.isAssignableFrom(m.getParameterTypes()[0])) {
                    setMappingMethod = m;
                    break;
                }
            }
            if (setMappingMethod != null) {
                setMappingMethod.invoke(result, currentMap);
            } else {
                // If no suitable constructor/setter, return the original mapping.
                return mappings;
            }
        }
        return result;
    } catch (Throwable e) {
        // In case of any reflection or instantiation issues, return the original mapping.
        return mappings;
    }
}

