        }
        @SuppressWarnings("unchecked")
        Map<String, Object> props = (Map<String, Object>) propsObj;

        // Create a copy of the properties map without the "_source" field
        Map<String, Object> cleanedProps = new LinkedHashMap<>(props);
        if (cleanedProps.containsKey("_source")) {
            cleanedProps.remove("_source");
