public static void createConfigurationDirectory() {
    try {
        String osName = System.getProperty("os.name");
        String osVersion = System.getProperty("os.version");
        boolean isWindows2000 = osName != null && osName.toLowerCase().contains("windows")
                && osVersion != null && osVersion.startsWith("5.0");

        String dirPath;
        if (isWindows2000) {
            String systemDrive = System.getenv("SystemDrive");
            if (systemDrive == null || systemDrive.isEmpty()) {
                systemDrive = "C:";
            }
            dirPath = systemDrive + File.separator + "Documents and Settings" + File.separator + "lf5";
        } else {
            String userHome = System.getProperty("user.home");
            if (userHome == null) {
                userHome = ".";
            }
            dirPath = userHome + File.separator + "lf5";
        }

        java.io.File dir = new java.io.File(dirPath);
        if (!dir.exists()) {
            if (!dir.mkdirs()) {
                System.err.println("Failed to create configuration directory: " + dirPath);
            }
        }
    } catch (Exception e) {
        System.err.println("Error creating configuration directory: " + e.getMessage());
    }
}

public static void createConfigurationDirectory() {
    String osName = System.getProperty("os.name");
    String basePath;
    if (osName != null && osName.contains("Windows 2000")) {
        // On Windows 2000 use the Documents and Settings directory
        basePath = "C:\\Documents and Settings";
    } else {
        // On other platforms use the user's home directory
        basePath = System.getProperty("user.home");
        if (basePath == null) {
            // If user.home is not set, fall back to root
            basePath = System.getProperty("user.dir", ".");
        }
    }

    java.io.File configDir = new java.io.File(basePath, "lf5");
    if (!configDir.exists()) {
        try {
            if (!configDir.mkdirs()) {
                // If directory creation failed for any reason, try to throw an exception
                System.err.println("Failed to create configuration directory: " + configDir.getAbsolutePath());
            }
        } catch (SecurityException e) {
            // Log the error; creation is not essential to throw
            System.err.println("Security exception while creating configuration directory: " + e.getMessage());
        }
    }
}

