    }
    boolean isWin2000 = osName != null && osName.startsWith("Windows") && osName.contains("2000");
    if (isWin2000) {
        java.io.File userHomeFile = new java.io.File(basePath);
        java.io.File docsAndSettings = userHomeFile.getParentFile();
        if (docsAndSettings != null && docsAndSettings.isDirectory()
                && "Documents and Settings".equalsIgnoreCase(docsAndSettings.getName())) {
            basePath = docsAndSettings.getAbsolutePath();
        }
    }
    java.io.File configDir = new java.io.File(basePath, "lf5");
    try {
        if (!configDir.exists()) {
            configDir.mkdirs();
        }
    } catch (SecurityException ignored) {
    }
}

