            }
            try {
                pw.print(message);
                pw.print("\r\n");
                pw.flush();
            } catch (Exception e) {
                // If writing fails (e.g., connection closed), remove the writer to prevent future errors
                it.remove();
            }
        }
    } catch (Exception e) {
        // Log the error or silently ignore; method should not throw
    }
}

