protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Ensure valid range
    if (start >= end || FETCH_DATA_DURATION <= 0) {
        return new java.util.ArrayList<>();
    }

    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    long cursor = start;

    while (cursor < end) {
        long nextEnd = cursor + FETCH_DATA_DURATION;
        if (nextEnd > end) {
            nextEnd = end;
        }
        ranges.add(new TimeRange(cursor, nextEnd));
        cursor = nextEnd;
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // If no range or invalid input, return empty list
    if (start >= end) {
        return ranges;
    }
    // If FETCH_DATA_DURATION is non-positive, treat the whole range as one chunk
    if (FETCH_DATA_DURATION <= 0) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next;
        // Prevent overflow when adding FETCH_DATA_DURATION
        if (Long.MAX_VALUE - current <= FETCH_DATA_DURATION) {
            next = end;
        } else {
            next = Math.min(current + FETCH_DATA_DURATION, end);
        }
        // Safety check to avoid infinite loop in pathological cases
        if (next <= current) {
            // In case of an unexpected situation, break to avoid endless loop
            break;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
