    }
    long currentStart = start;
    while (currentStart < end) {
        long potentialEnd = currentStart + FETCH_DATA_DURATION;
        // Handle overflow
        if (potentialEnd < 0 || potentialEnd > end) {
            potentialEnd = end;
        }
        // Ensure progress
        if (potentialEnd <= currentStart) {
