        }
        ranges.add(new TimeRange(currentStart, potentialEnd));
        currentStart = potentialEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input boundaries
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time.");
    }
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non‑negative.");
    }

    // Ensure the split duration is valid
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive.");
    }

    List<TimeRange> ranges = new ArrayList<>();
    if (start == end) {
        return ranges; // No duration to cover
    }

    long step = FETCH_DATA_DURATION;
    long current = start;
    try {
        while (current < end) {
            long next = current + step;
            // Protect against overflow and cap at end
            if (next <= current || next > end) {
                next = end;
            }
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception e) {
        throw new RuntimeException("Error while building time ranges", e);
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }

    long step = FETCH_DATA_DURATION;
    if (step <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }

    while (start < end) {
        long nextEnd;
        try {
            nextEnd = Math.min(end, Math.addExact(start, step));
        } catch (ArithmeticException e) {
            // In case of overflow, cap at end
            nextEnd = end;
        }
        ranges.add(new TimeRange(start, nextEnd));
        start = nextEnd;
    }

    return ranges;
}

