        if(this.size > 0){
            System.arraycopy(this.data, 0, newData, 0, this.size);
        }
        this.data = newData;
        this.capacity = newCap;
    }

    // Copy bytes
    if(byteArrayValue == null){
        // Fill with null bytes (zeros)
        for (int i = 0; i < byteLength; i++) {
            this.data[this.size + i] = 0;
        }
