    if(requiredCapacity > buffer.length){
        int newCapacity = Math.max(buffer.length * 2, requiredCapacity);
        buffer = java.util.Arrays.copyOf(buffer, newCapacity);
    }
    if(byteArrayValue == null){
        java.util.Arrays.fill(buffer, size, size + byteLength, (byte)0);
        size += byteLength;
