        throw new IllegalArgumentException("byteLength cannot be negative, but was: " + byteLength);
    }
    // Validate offset and available length if array is provided
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset out of bounds: " + byteOffset);
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException(
                "byteOffset + byteLength exceeds array length: " + (byteOffset + byteLength));
        }
    }

    // Ensure capacity
    int requiredPos = pos + byteLength;
    if (requiredPos > buffer.length) {
        int newCapacity = buffer.length * 2;
        if (newCapacity < requiredPos) {
            newCapacity = requiredPos;
        }
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, pos);
        buffer = newBuffer;
    }

    // Copy bytes or fill with zeros
    if (byteArrayValue != null && byteLength > 0) {
        System.arraycopy(byteArrayValue, byteOffset, buffer, pos, byteLength);
    } else if (byteLength > 0) {
        for (int i = pos; i < requiredPos; i++) {
            buffer[i] = 0;
        }
    }

    pos = requiredPos;
    return this;
}

