    }
    // Common explicit separators
    switch (c) {
        case ' ': case '\t': case '\n': case '\r':
        case '=': case ';': case '&': case ',': case '?':
            return true;
        default:
            // Characters allowed in a parameter name
            if ((c >= 'a' && c <= 'z') ||
                (c >= 'A' && c <= 'Z') ||
                (c >= '0' && c <= '9') ||
                c == '-' || c == '_' || c == '.') {
                return false;
            }
            // Any other character is treated as a separator
            return true;
    }
}

