    // - whitespace characters (space, tab, newline, return)
    // - punctuation that typically separates parameters
    //   such as commas, semicolons, brackets, brackets, braces, parentheses, pipes.
    switch (c) {
        case ' ':
        case '\t':
        case '\n':
        case '\r':
            return true;
        case ',':
        case ';':
        case '|':
        case '[':
        case ']':
        case '(':
        case ')':
        case '{':
        case '}':
            return true;
        default:
            return Character.isWhitespace(c);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match
