        if (o1 == null) {
            if (o2 == null) {
                return 0; // both null are considered equal
            }
            return -1; // null is less than non-null
        }
        if (o2 == null) {
            return 1; // non-null is greater than null
        }

        // Use Double's natural ordering
        double comparison = o1.compareTo(o2);

        if (comparison < 0) {
            return -1;
        } else if (comparison > 0) {
            return 1;
        } else {
            return 0; // values are considered equal
        }
    }

@Override
public int compare(Double o1, Double o2) {
    try {
        if (o1 == null && o2 == null) {
            return 0;
        }
        if (o1 == null) {
            return -1;
        }
        if (o2 == null) {
            return 1;
        }
        int cmp = Double.compare(o1, o2);
        if (cmp < 0) {
            return -1;
        } else if (cmp > 0) {
            return 1;
        } else {
            return 0;
        }
    } catch (Exception e) {
        // In case of unexpected errors, propagate as runtime exception
        throw new IllegalStateException("Error comparing Doubles", e);
    }
}

@Override
public int compare(Double o1, Double o2) {
    // Handle nulls: treat null as less than any non-null value
    if (o1 == null) {
        return (o2 == null) ? 0 : -1;
    }
    if (o2 == null) {
        return 1;
    }

    int cmp = Double.compare(o1, o2);
    if (cmp < 0) {
        return -1;
    } else if (cmp > 0) {
        return 1;
    } else {
        return 0;
    }
}

@Override public int compare(Double o1,Double o2){
    if (o1 == null || o2 == null) {
        throw new IllegalArgumentException("Null values are not allowed for comparison");
    }
    int cmp = Double.compare(o1, o2);
    return cmp < 0 ? -1 : (cmp > 0 ? 1 : 0);
}

