public static String capitalize(String name) {
    // Handle null or empty input
    if (name == null || name.isEmpty()) {
        return name;
    }
    // If first two characters are uppercase, Introspector.decapitalize would not change the string,
    // so we keep it unchanged.
    if (name.length() > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise convert the first character to uppercase
    char[] chars = name.toCharArray();
    chars[0] = Character.toUpperCase(chars[0]);
    return new String(chars);
}

public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    // If first two characters are already uppercase, do nothing
    if (name.length() >= 2) {
        char first = name.charAt(0);
        char second = name.charAt(1);
        if (Character.isUpperCase(first) && Character.isUpperCase(second)) {
            return name;
        }
    }
    // Otherwise, convert first character to uppercase
    char first = name.charAt(0);
    char capitalFirst = Character.toUpperCase(first);
    if (capitalFirst == first) {
        return name; // No change needed
    }
    return capitalFirst + name.substring(1);
}

