    // Handle null or empty strings gracefully
    if (name == null || name.isEmpty()) {
        return name;
    }

    // Per Introspector.decapitalize, if the first two characters are uppercase,
    // the string is considered an acronym and should remain unchanged.
    if (name.length() > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }

    // Otherwise, capitalise the first character (leave the rest unchanged)
    char[] chars = name.toCharArray();
    chars[0] = Character.toUpperCase(chars[0]);

    return new String(chars);
}

