public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        long timestamp = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        String date = sdf.format(new java.util.Date(timestamp));

        String level = (event.getLevel() != null) ? event.getLevel().toString() : "UNKNOWN_LEVEL";
        String thread = (event.getThreadName() != null) ? event.getThreadName() : "UNKNOWN_THREAD";
        String logger = (event.getLoggerName() != null) ? event.getLoggerName() : "UNKNOWN_LOGGER";
        String message = (event.getFormattedMessage() != null) ? event.getFormattedMessage() : "";

        StringBuilder sb = new StringBuilder();
        sb.append('[').append(date).append("] ")
          .append('[').append(level).append("] ")
          .append('[').append(thread).append("] ")
          .append('[').append(logger).append("] - ")
          .append(message);

        return sb.toString();
    } catch (Exception e) {
        return "Error formatting LoggingEvent: " + e.getMessage();
    }
}

