public static int nextPrime(int desiredCapacity){
    // Handle trivial cases
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Avoid negative or overflow values
    int candidate = desiredCapacity;
    // Ensure candidate is odd (even numbers > 2 cannot be prime)
    if ((candidate & 1) == 0) {
        candidate++;
    }

    while (true) {
        // Check for overflow before performing further operations
        if (candidate < 0) {
            throw new IllegalArgumentException("Desired capacity is too large to find a prime");
        }

        if (isPrime(candidate)) {
            return candidate;
        }

        // Increment to the next odd number
        if (candidate >= Integer.MAX_VALUE - 2) {
            // Next odd would overflow
            throw new IllegalArgumentException("No prime number available within integer range");
        }
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    int n = desiredCapacity;
    if ((n & 1) == 0) {
        n++; // start at odd number
    }
    while (true) {
        if (isPrime(n)) {
            return n;
        }
        n += 2; // skip even numbers
        if (n <= 0) { // overflow protection
            return 2147483647; // largest prime before overflow
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // ensure candidate is odd
    }
    while (true) {
        if (candidate <= 3) {
            return candidate; // 2 or 3, already prime
        }
        if (candidate % 2 == 0 || candidate % 3 == 0) {
            candidate += 2; // skip to next odd candidate
            continue;
        }
        boolean composite = false;
        int sqrt = (int) Math.sqrt(candidate);
        for (int i = 5; i <= sqrt; i += 6) {
            if (candidate % i == 0 || candidate % (i + 2) == 0) {
                composite = true;
                break;
            }
        }
        if (!composite) {
            return candidate; // found prime
        }
        candidate += 2; // try next odd number
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    // limit within 11% if desiredCapacity >= 1000
    long upperLimit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long tempLimit = Math.round(desiredCapacity * 1.11) + 1;
        if (tempLimit < 0 || tempLimit > Integer.MAX_VALUE) {
            upperLimit = Integer.MAX_VALUE;
        } else {
            upperLimit = tempLimit;
        }
    }
    while (candidate >= 0 && candidate <= upperLimit) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
    // If not found within the 11% range, continue searching beyond the limit
    while (candidate >= 0 && candidate <= Integer.MAX_VALUE) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }
    throw new IllegalArgumentException("Cannot find a prime within int range for desiredCapacity: " + desiredCapacity);
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Make candidate odd if it is even and not 2
    if (candidate % 2 == 0) {
        candidate++;
    }
    // If desiredCapacity is large, limit search to Integer.MAX_VALUE
    while (candidate <= Integer.MAX_VALUE) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid overflow when incrementing
        if (candidate == Integer.MAX_VALUE) {
            break;
        }
        candidate += 2;
    }
    // If we reach here, no prime found (only possible if desiredCapacity is Integer.MAX_VALUE)
    // In practice this should never happen for valid inputs.
    return Integer.MAX_VALUE;
}

