@Override
public String readString() throws IOException {
    try {
        // Read the length of the string; conventionally -1 indicates null
        int length = in.readInt();
        if (length < 0) {
            return null;
        }
        if (length == 0) {
            return "";
        }
        // Read exactly 'length' bytes
        byte[] bytes = new byte[length];
        int offset = 0;
        while (offset < length) {
            int read = in.read(bytes, offset, length - offset);
            if (read == -1) {
                throw new EOFException("Unexpected end of stream while reading string");
            }
            offset += read;
        }
        // Convert bytes to a string using UTF-8 encoding
        try {
            return new String(bytes, "UTF-8");
        } catch (java.io.UnsupportedEncodingException e) {
            throw new IOException("UTF-8 encoding not supported", e);
        }
    } catch (java.io.EOFException e) {
        throw new IOException("Failed to read string: unexpected end of stream", e);
    }
}

