public final byte[] toByteArray(){
    java.io.ByteArrayOutputStream combined = new java.io.ByteArrayOutputStream();
    try {
        Class<?> clazz = this.getClass();
        while (clazz != null) {
            java.lang.reflect.Field[] fields = clazz.getDeclaredFields();
            for (java.lang.reflect.Field f : fields) {
                f.setAccessible(true);
                Object val = f.get(this);
                if (val == null) continue;
                if (val instanceof byte[]) {
                    combined.write((byte[]) val);
                } else if (val instanceof java.nio.ByteBuffer) {
                    java.nio.ByteBuffer bb = (java.nio.ByteBuffer) val;
                    int pos = bb.position();
                    int lim = bb.limit();
                    byte[] arr = new byte[lim - pos];
                    bb.get(arr);
                    combined.write(arr);
                    bb.position(pos);
                } else if (val instanceof java.io.ByteArrayOutputStream) {
                    combined.write(((java.io.ByteArrayOutputStream) val).toByteArray());
                } else if (val instanceof java.util.Collection) {
                    for (Object o : (java.util.Collection<?>) val) {
                        if (o instanceof byte[]) {
                            combined.write((byte[]) o);
                        } else if (o instanceof java.io.ByteArrayOutputStream) {
                            combined.write(((java.io.ByteArrayOutputStream) o).toByteArray());
                        }
                    }
                }
            }
            clazz = clazz.getSuperclass();
        }
        return combined.toByteArray();
    } catch (Exception e) {
        return new byte[0];
    }
}

