static String[] toNoNullStringArray(Collection<?> collection){
    if (collection == null) {
        return new String[0];
    }
    List<String> result = new ArrayList<>();
    for (Object obj : collection) {
        if (obj != null) {
            try {
                result.add(obj.toString());
            } catch (Exception e) {
                // If toString() throws an exception, skip this element
                // and continue with the rest.
            }
        }
    }
    return result.toArray(new String[0]);
}

static String[] toNoNullStringArray(Collection<?> collection){
    // Return an empty array if the incoming collection is null
    if (collection == null) {
        return new String[0];
    }

    // Use a list to accumulate non-null string representations
    List<String> tmp = new ArrayList<>(collection.size());
    for (Object element : collection) {
        if (element != null) {
            String str = String.valueOf(element);
            // Skip elements whose string conversion returns null
            if (str != null) {
                tmp.add(str);
            }
        }
    }

    // Convert the list to a String array and return it
    return tmp.toArray(new String[0]);
}

