protected int removeUnusedNodes() {
    int removed = 0;
    try {
        // Retrieve the root of the category tree.
        Category root = getRoot();
        if (root == null) {
            return 0; // Nothing to remove.
        }

        // If the root itself is inactive, discard the entire tree.
        if (!root.isActive()) {
            setRoot(null);
            return 1; // Only the root was removed.
        }

        // Use two stacks to keep track of nodes and their parents.
        ArrayDeque<Category> childStack = new ArrayDeque<>();
        ArrayDeque<Category> parentStack = new ArrayDeque<>();

        // Initialize the stacks with the root's immediate children.
        for (Category child : safeChildren(root)) {
            childStack.push(child);
            parentStack.push(root);
        }

        // Traverse the tree iteratively.
        while (!childStack.isEmpty()) {
            Category child = childStack.pop();
            Category parent = parentStack.pop();

            if (child == null) {
                continue;
            }

            if (child.isActive()) {
                // Continue traversal through active nodes.
                for (Category c : safeChildren(child)) {
                    childStack.push(c);
                    parentStack.push(child);
                }
            } else {
                // Inactive node found; remove it from its parent.
                try {
                    parent.removeChild(child);
                    removed++;
                } catch (Exception e) {
                    // If removal fails (e.g., child not actually in parent's list),
                    // we continue without counting this node.
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return -1 to signal failure.
        removed = -1;
    }
    return removed;
}

