    try {
        // Assume a field named 'root' holds the root of the Category tree
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, delete it entirely
        if (!root.isActive()) {
            root = null;
            return 1;
        }
        // Recursively process the tree
        removed = removeInactiveRecursively(root);
    } catch (Exception e) {
        // If a logger is available, log the exception
        // For example: logger.warn("Failed to remove unused nodes", e);
    }
    return removed;
}

