private void check(String modelName) throws IllegalStateException {
    // Retrieve sharding key indices for the specified model
    java.util.List<Integer> indices = ShardingMetadata.getShardingKeyIndicesForModel(modelName);
    if (indices == null || indices.isEmpty()) {
        throw new IllegalStateException("No sharding keys defined for model: " + modelName);
    }
    // Sort indices to verify continuity
    java.util.List<Integer> sorted = new java.util.ArrayList<>(indices);
    java.util.Collections.sort(sorted);
    for (int i = 0; i < sorted.size(); i++) {
        if (sorted.get(i) != i) {
            throw new IllegalStateException(
                "Sharding key indices for model " + modelName
                + " are not continuous. Expected indices 0.." + (sorted.size() - 1)
                + " but found: " + indices);
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalStateException("Model name cannot be null or empty");
    }
    try {
        Class<?> clazz = Class.forName(modelName);
        Field[] fields = clazz.getDeclaredFields();
        java.util.List<Integer> indices = new java.util.ArrayList<>();
        for (Field field : fields) {
            Annotation[] annos = field.getAnnotations();
            for (Annotation anno : annos) {
                try {
                    java.lang.reflect.Method m = anno.annotationType().getMethod("index");
                    Object val = m.invoke(anno);
                    if (val instanceof Integer) {
                        indices.add((Integer) val);
                        break; // assume one sharding index per field
                    }
                } catch (NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
                    // not an annotation with an index method, ignore
                }
            }
        }
        if (indices.isEmpty()) {
            return;
        }
        java.util.Collections.sort(indices);
        int expected = indices.get(0);
        for (int idx : indices) {
            if (idx != expected) {
                throw new IllegalStateException(
                    "Sharding key indices are not continuous for model " + modelName);
            }
            expected++;
        }
    } catch (ClassNotFoundException | IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
        throw new IllegalStateException(
            "Failed to check sharding keys for model " + modelName + ": " + e.getMessage(), e);
    }
}

private void check(String modelName) throws IllegalStateException {
    // Retrieve the list of sharding key indices for the specified model.
    // It is assumed that a map named `shardingKeyIndicesMap` exists in this class.
    if (modelName == null) {
        throw new IllegalStateException("Model name cannot be null");
    }
    List<Integer> indices = shardingKeyIndicesMap.get(modelName);
    if (indices == null) {
        throw new IllegalStateException("No sharding key indices defined for model: " + modelName);
    }
    if (indices.isEmpty()) {
        // An empty sharding key set is considered continuous for this context.
        return;
    }

    // Create a sorted copy to evaluate continuity.
    List<Integer> sorted = new ArrayList<>(indices);
    Collections.sort(sorted);

    // Verify that consecutive indices differ by exactly 1.
    for (int i = 1; i < sorted.size(); i++) {
        int prev = sorted.get(i - 1);
        int curr = sorted.get(i);
        if (curr - prev != 1) {
            throw new IllegalStateException("Sharding key indices for model " + modelName
                    + " are not continuous. Expected index after " + prev + " but found " + curr);
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    if (modelName == null) {
        throw new IllegalStateException("Model name cannot be null");
    }
    // Expect format: "modelName:idx1,idx2,idx3"
    int colonIndex = modelName.indexOf(':');
    if (colonIndex <= 0 || colonIndex == modelName.length() - 1) {
        return; // nothing to check
    }
    String indicesPart = modelName.substring(colonIndex + 1).trim();
    if (indicesPart.isEmpty()) {
        return;
    }
    String[] idxStrs = indicesPart.split(",");
    int[] idxs = new int[idxStrs.length];
    for (int i = 0; i < idxStrs.length; i++) {
        try {
            idxs[i] = Integer.parseInt(idxStrs[i].trim());
        } catch (NumberFormatException e) {
            throw new IllegalStateException("Invalid sharding key index: " + idxStrs[i], e);
        }
    }
    java.util.Arrays.sort(idxs);
    int expected = idxs[0];
    for (int i = 0; i < idxs.length; i++) {
        if (idxs[i] != expected + i) {
            throw new IllegalStateException("Sharding key indices must be continuous but found: "
                    + java.util.Arrays.toString(idxs));
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    if (modelName == null) {
        throw new IllegalArgumentException("modelName cannot be null");
    }
    try {
        Class<?> clazz = Class.forName(modelName);
        java.lang.reflect.Field[] fields = clazz.getDeclaredFields();
        java.util.TreeMap<Integer, java.lang.reflect.Field> indexMap = new java.util.TreeMap<>();
        for (java.lang.reflect.Field field : fields) {
            ShardingKey key = field.getAnnotation(ShardingKey.class);
            if (key != null) {
                int idx = key.index();
                if (indexMap.containsKey(idx)) {
                    throw new IllegalStateException(
                            String.format("Duplicate sharding key index %d in model %s for field %s", idx, modelName, field.getName()));
                }
                indexMap.put(idx, field);
            }
        }
        if (indexMap.isEmpty()) {
            // No sharding keys defined; nothing to validate.
            return;
        }
        int expectedIdx = 0;
        for (int actualIdx : indexMap.keySet()) {
            if (actualIdx != expectedIdx) {
                throw new IllegalStateException(
                        String.format("Sharding key indices are not continuous for model %s: expected index %d but found %d (field %s)",
                                modelName, expectedIdx, actualIdx, indexMap.get(actualIdx).getName()));
            }
            expectedIdx++;
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalArgumentException("Model class not found: " + modelName, e);
    }
}

