@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        // Determine the transport name in a type-agnostic way
        String transport = r.getTransport() != null ? String.valueOf(r.getTransport()) : null;
        // Suspend for all transports except WebSocket (which keeps the connection alive)
        if (transport != null && !transport.equalsIgnoreCase("websocket")) {
            try {
                // Suspend the resource
                r.suspend();
            } catch (Throwable t) {
                // Ignore any exceptions from suspend execution
            }
        }
    } catch (Throwable e) {
        // Ignore any unexpected exception while inspecting
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    String transport;
    try {
        transport = r.getTransport();
    } catch (Exception e) {
        // Fallback if getTransport throws
        transport = null;
    }
    if (transport == null) {
        return Action.CONTINUE;
    }
    // Do not auto‑suspend transports that already support push (e.g. websocket, SSE, source)
    if (transport.equalsIgnoreCase(AtmosphereResource.TRANSPORT_WEBSOCKET) ||
        transport.equalsIgnoreCase(AtmosphereResource.TRANSPORT_BROWSER_SSE) ||
        transport.equalsIgnoreCase(AtmosphereResource.TRANSPORT_SOURCE)) {
        return Action.CONTINUE;
    }
    try {
        // Attempt to suspend the resource. Some transports may already be suspended; ignore any exception.
        r.suspend();
    } catch (Exception ignored) {
        // Ignore any suspension failure; the caller can handle it if needed.
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    try {
        if (r == null) {
            return Action.CONTINUE;
        }
        String transport = r.getTransport();
        if (transport != null) {
            // Normalize transport value
            String t = transport.trim().toLowerCase();
            // Suspend for long polling or websocket-like transports that require suspension
            if ("long-polling".equals(t) || "longpolling".equals(t) || "websocket".equals(t)) {
                // Suspend with default timeout (0 means no timeout)
                r.suspend(0);
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, we simply log if SLF4J is available or ignore
        try { (System.err).println("Error in inspect: " + e.getMessage()); } catch (Exception ignored) {}
