@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        // If already suspended, nothing to do
        if (r.isSuspended()) {
            return Action.CONTINUE;
        }
        // Determine the transport type
        String transport = r.getTransport();
        if (transport == null) {
            // Unknown transport, treat as non-WebSocket and suspend
            r.suspend();
        } else {
            // Only suspend for non‑WebSocket transports
            String t = transport.trim().toLowerCase(Locale.ROOT);
            if (!t.equals("websocket") && !t.equals("ws")) {
                r.suspend();
            }
        }
    } catch (Exception e) {
