    }
    return Action.CONTINUE;
}

@Override
public Action inspect(AtmosphereResource r) {
    // Ensure we don't throw any runtime exceptions during inspection
    try {
        // Defensive check for null resource
        if (r == null) {
            return Action.CONTINUE;
        }

        // Retrieve the transport type, handling the possibility that the call might throw
        String transport = r.getTransport();
        if (transport == null) {
            return Action.CONTINUE;
        }

        // Auto‑suspend if the transport is a long‑polling protocol and not already suspended
        // Includes common names used in Atmosphere for long‑polling transports
        if (!r.isSuspended()) {
            String t = transport.trim().toLowerCase();
            if ("long-polling".equals(t) || "comet".equals(t) || "longpolling".equals(t) 
