            // Assume a method getIncomingEdges() is defined for vertex
            @SuppressWarnings("unchecked")
            Iterable<Object> edges = (Iterable<Object>) vertex.getClass()
                    .getMethod("getIncomingEdges")
                    .invoke(vertex);
            if (edges != null) {
                for (Object e : edges) {
                    if (e == null) continue;
                    try {
                        double weight = (double) e.getClass()
                                .getMethod("getWeight")
                                .invoke(e);
                        sum += weight;
                    } catch (Exception ignored) {
                        // Skip edges whose weight cannot be retrieved
                    }
                }
            }
        } catch (Exception ignored) {
            // Skip vertices without defined incoming edges
        }
    }
    return sum;
}

public double vertexWeight(Set<V> v){
    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null");
    }
    double sum = 0.0;
    try {
        // Assume the graph stores outgoing edges in a map: source -> (target -> weight)
        if (adjacency == null) {
            return 0.0;
        }
        for (Map.Entry<V, Map<V, Double>> srcEntry : adjacency.entrySet()) {
            Map<V, Double> targets = srcEntry.getValue();
            if (targets == null) {
                continue;
            }
            for (Map.Entry<V, Double> edgeEntry : targets.entrySet()) {
                V target = edgeEntry.getKey();
                Double weight = edgeEntry.getValue();
                if (v.contains(target) && weight != null) {
                    sum += weight;
                }
            }
        }
    } catch (Exception e) {
        // Log the exception or rethrow as a runtime exception with context
        throw new RuntimeException("Failed to compute vertex weight.", e);
    }
    return sum;
}

