    // Handle reference equality and nulls first
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null) {
        return -1; // null is considered less than any non‑null
    }
    if (aObj2 == null) {
        return 1;  // any non‑null is greater than null
    }

    // If both objects implement Comparable, delegate comparison
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> cmp = (Comparable<Object>) aObj1;
            return cmp.compareTo(aObj2);
        } catch (ClassCastException e) {
            // If the target type is incompatible, throw a clear exception
            throw new ClassCastException(
                "Incompatible types for comparison: " +
                aObj1.getClass().getName() + " vs " + aObj2.getClass().getName());
        }
    }

    // If they are not mutually Comparable, fail fast
    throw new ClassCastException("Objects are not Comparable");
}

