public int appendLoopOnAppenders(LoggingEvent event){
    int missingAppenderCount = 0;
    if (event == null) {
        return missingAppenderCount;
    }
    Enumeration<?> enm = getAllAppenders();
    if (enm == null) {
        return missingAppenderCount;
    }
    while (enm.hasMoreElements()) {
        Object obj = enm.nextElement();
        if (obj == null) {
            missingAppenderCount++;
            continue;
        }
        Appender appender;
        try {
            appender = (Appender) obj;
        } catch (ClassCastException ex) {
            // Skip any invalid appender
            missingAppenderCount++;
            continue;
        }
        try {
            appender.doAppend(event);
        } catch (Throwable t) {
            // Silently ignore any exception thrown by an appender
        }
    }
    return missingAppenderCount;
}

