protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null || tour.isEmpty()) {
        return null;
    }
    try {
        Map<V, List<E>> adjacency = new HashMap<>();
        for (E e : tour) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
            if (!src.equals(tgt)) {
                adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
            }
        }
        // Pick an arbitrary start vertex from the first edge
        E firstEdge = tour.iterator().next();
        V start = graph.getEdgeSource(firstEdge);
        List<E> edgeList = new ArrayList<>();
        List<V> vertexList = new ArrayList<>();
        Set<E> visited = new HashSet<>();
        vertexList.add(start);
        V current = start;
        while (visited.size() < tour.size()) {
            List<E> edgesAtCurr = adjacency.get(current);
            if (edgesAtCurr == null) {
                return null;
            }
            E nextEdge = null;
            for (E e : edgesAtCurr) {
                if (!visited.contains(e)) {
                    nextEdge = e;
                    break;
                }
            }
            if (nextEdge == null) {
                return null; // No unvisited edge found, invalid tour
            }
            edgeList.add(nextEdge);
            visited.add(nextEdge);
            V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                    ? graph.getEdgeTarget(nextEdge)
                    : graph.getEdgeSource(nextEdge);
            vertexList.add(nextVertex);
            current = nextVertex;
        }
        V end = current;
        return new GraphPathImpl<>(graph, start, end, edgeList, vertexList);
    } catch (Exception e) {
        return null;
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour set and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Verify that all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " does not belong to the graph");
        }
    }

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);

    // Start construction from an arbitrary edge
    E startEdge = remaining.iterator().next();
    V start = graph.getEdgeSource(startEdge);
    V next = graph.getEdgeTarget(startEdge);
    vertexList.add(start);
    vertexList.add(next);
    edgeList.add(startEdge);
    remaining.remove(startEdge);

    V current = next;
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> it = remaining.iterator();
        while (it.hasNext()) {
            E e = it.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                vertexList.add(tgt);
                edgeList.add(e);
                current = tgt;
                it.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) {
                vertexList.add(src);
                edgeList.add(e);
                current = src;
                it.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException(
                "Cannot construct a continuous path from the given set of edges");
        }
    }

    V source = vertexList.get(0);
    V target = vertexList.get(vertexList.size() - 1);

    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, source, target, vertexList, edgeList, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null)
        throw new IllegalArgumentException("tour cannot be null");
    if (graph == null)
        throw new IllegalArgumentException("graph cannot be null");
    if (tour.isEmpty())
        return null;

    // Validate all edges belong to the graph
    for (E e : tour) {
        if (!graph.containsEdge(e))
            throw new IllegalArgumentException("Edge " + e + " not in graph");
    }

    // Build adjacency map: vertex -> set of incident edges
    Map<V, Set<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new HashSet<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new HashSet<>()).add(e);
    }

    // Choose an arbitrary start edge and start vertex
    E startEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(startEdge);

    // Prepare lists for the path
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    vertexList.add(startVertex);
    V current = startVertex;

    Set<E> remainingEdges = new HashSet<>(tour);

    while (!remainingEdges.isEmpty()) {
        Set<E> incident = adjacency.get(current);
        if (incident == null)
            break;
        E chosen = null;
        for (E e : incident) {
            if (remainingEdges.contains(e)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null)
            break; // dead end

        // Remove the chosen edge from remaining and from adjacency sets
        remainingEdges.remove(chosen);
        adjacency.get(graph.getEdgeSource(chosen)).remove(chosen);
        adjacency.get(graph.getEdgeTarget(chosen)).remove(chosen);

        edgeList.add(chosen);

        // Move to the next vertex
        V next = graph.getEdgeSource(chosen).equals(current)
                 ? graph.getEdgeTarget(chosen)
                 : graph.getEdgeSource(chosen);
        vertexList.add(next);
        current = next;
    }

    V endVertex = current;
    // If the path forms a cycle, ensure the end vertex is the same as the start
    if (!vertexList.isEmpty() && vertexList.get(vertexList.size() - 1).equals(startVertex) && !edgeList.isEmpty()) {
        endVertex = startVertex;
    }

    // Create and return the GraphPath (GraphWalk implementation)
    return new GraphWalk<>(graph, startVertex, endVertex, vertexList, edgeList);
}

