int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    if (this.constantPool == null) {
        throw new IllegalStateException("Constant pool is not initialized");
    }
    // Use a simple pair key for lookup
    final class Key {
        final String n, d;
        Key(String n, String d){ this.n=n; this.d=d; }
        @Override public boolean equals(Object o){
            if (this==o) return true;
            if (!(o instanceof Key)) return false;
            Key k=(Key)o;
            return n.equals(k.n) && d.equals(k.d);
        }
        @Override public int hashCode(){ return n.hashCode()*31 + d.hashCode(); }
    }
    Key key = new Key(name, descriptor);
    Integer existing = this.constantIndexMap.get(key);
    if (existing != null) {
        return existing;
    }
    // Create the new constant pool entry
    ConstantNameAndTypeInfo entry;
    try {
        entry = new ConstantNameAndTypeInfo(name, descriptor);
    } catch (Exception e) {
        throw new RuntimeException("Failed to create ConstantNameAndTypeInfo", e);
    }
    this.constantPool.add(entry);
    int idx = this.constantPool.size() - 1;
    this.constantIndexMap.put(key, idx);
    return idx;
}

int addConstantNameAndType(final String name, final String descriptor){
    // Defensive null / empty checks
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null.");
    }

    // Use a combined key to locate an existing entry
    final String key = name + '\0' + descriptor; // '\0' separates name from descriptor

    // If the mapping already exists, simply return its index
    Integer existingIndex = this.nameAndTypeIndices.get(key);
    if (existingIndex != null) {
        return existingIndex;
    }

    try {
        // Ensure the Utf8 entries for name and descriptor exist
        int nameIdx = this.addConstantUtf8(name);
        int descIdx = this.addConstantUtf8(descriptor);

        // Create the new NameAndType constant pool entry
        ConstantPoolInfo entry = new ConstantPoolInfo((byte)12, nameIdx, descIdx);
        this.constantPool.add(entry);

        // The constant pool is 1‑based, so the new index is the size of the list
        int newIndex = this.constantPool.size();

        // Cache the mapping for future lookups
        this.nameAndTypeIndices.put(key, newIndex);

        return newIndex;
    } catch (Exception e) {
        // If anything goes wrong, wrap and re‑throw as a RuntimeException
        throw new RuntimeException("Failed to add CONSTANT_NameAndType_info to constant pool", e);
    }
}

int addConstantNameAndType(final String name, final String descriptor) {
    // Validate parameters
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }

    // Search for an existing CONSTANT_NameAndType_info entry
    for (int i = 0; i < constantPool.size(); i++) {
        Object entry = constantPool.get(i);
        if (entry instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info nti = (CONSTANT_NameAndType_info) entry;
            if (name.equals(nti.getName()) && descriptor.equals(nti.getDescriptor())) {
                // Constant pool indices are 1-based
                return i + 1;
            }
        }
    }

    // Not found – create a new entry
    CONSTANT_NameAndType_info newEntry = new CONSTANT_NameAndType_info(name, descriptor);
    constantPool.add(newEntry);

    // Return the new index (1-based)
    return constantPool.size();
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null) {
        throw new IllegalArgumentException("name cannot be null");
    }
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }

    try {
        // Ensure that both UTF-8 constants exist and obtain their indices
        int nameIndex = addConstantUtf8(name);
        int descriptorIndex = addConstantUtf8(descriptor);

        // Look for an existing NameAndType entry with the same name and descriptor indices
        for (int i = 0; i < constantPool.size(); i++) {
            Object entry = constantPool.get(i);
            if (entry instanceof ConstantNameAndTypeInfo) {
                ConstantNameAndTypeInfo nti = (ConstantNameAndTypeInfo) entry;
                if (nti.getNameIndex() == nameIndex && nti.getDescriptorIndex() == descriptorIndex) {
                    return i;
                }
            }
        }

        // If not found, create a new NameAndType constant pool entry
        ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
        constantPool.add(newEntry);
        return constantPool.size() - 1;

    } catch (Exception e) {
        // Wrap any unexpected errors in a runtime exception for clarity
        throw new RuntimeException("Failed to add CONSTANT_NameAndType_info to constant pool", e);
    }
}

int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    try {
        java.lang.reflect.Field cpField = this.getClass().getDeclaredField("constantPool");
        cpField.setAccessible(true);
        Object constantPool = cpField.get(this);
        java.lang.reflect.Method addMethod = constantPool.getClass()
            .getMethod("addConstantNameAndTypeInfo", java.lang.String.class, java.lang.String.class);
        Object result = addMethod.invoke(constantPool, name, descriptor);
        if (result instanceof Integer) {
            return (Integer) result;
        } else {
            throw new IllegalStateException("Unexpected return type from constantPool.addConstantNameAndTypeInfo");
        }
    } catch (NoSuchFieldException | NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException e) {
        throw new RuntimeException("Failed to add constant name and type to the pool", e);
    }
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Remove surrounding quotes or braces
    String work = input;
    if (work.length() >= 2) {
        char first = work.charAt(0);
        char last = work.charAt(work.length() - 1);
        if ((first == '"' && last == '"') || (first == '{' && last == '}')) {
            work = work.substring(1, work.length() - 1);
        }
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < work.length(); i++) {
        char c = work.charAt(i);
        if (c == '\\' && i + 1 < work.length()) {
            char next = work.charAt(++i);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '{':
                    sb.append('{');
                    break;
                case '}':
                    sb.append('}');
                    break;
                case 'a':
                    sb.append('\u0007');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B');
                    break;
                case 'x':
                    // Hexadecimal escape \xHH
                    int hexLen = 0;
                    int hexVal = 0;
                    while (i + 1 < work.length() && hexLen < 2) {
                        char h = work.charAt(i + 1);
                        int digit = Character.digit(h, 16);
                        if (digit == -1) {
                            break;
                        }
                        hexVal = (hexVal << 4) + digit;
                        i++;
                        hexLen++;
                    }
                    sb.append((char) hexVal);
                    break;
                case 'u':
                    // Unicode escape \uHHHH
                    int uLen = 0;
                    int uVal = 0;
                    while (i + 1 < work.length() && uLen < 4) {
                        char h = work.charAt(i + 1);
                        int digit = Character.digit(h, 16);
                        if (digit == -1) {
                            break;
                        }
                        uVal = (uVal << 4) + digit;
                        i++;
                        uLen++;
                    }
                    sb.append((char) uVal);
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        // Octal escape \NNN (up to 3 octal digits)
                        int octVal = next - '0';
                        int octCount = 1;
                        while (i + 1 < work.length() && octCount < 3) {
                            char d = work.charAt(i + 1);
                            if (d >= '0' && d <= '7') {
                                octVal = (octVal << 3) + (d - '0');
                                i++;
                                octCount++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) octVal);
                    } else {
                        // Unknown escape: keep as is
                        sb.append(next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

