                        }
                        i += 6;
                    } else {
                        // invalid escape, keep 'u'
                        sb.append('u');
                        i += 2;
                    }
                    break;
                }
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case 'b':
                    sb.append('\b');
                    i += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 2;
                    break;
                case 'a':
                    sb.append('\u0007');
                    i += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 2;
                    break;
                default:
                    sb.append(esc);
                    i += 2;
                    break;
            }
        }
    }
    return sb.toString();
}

