@Override
public boolean hasNext() {
    try {
        // If the entire graph structure is not initialized, there are no unvisited vertices
        if (vertices == null) {
            return false;
        }

        // If the visited set hasn't been created yet, consider that no vertices have been visited
        if (visited == null) {
            // If the graph has at least one vertex, there will be unvisited ones
            return !vertices.isEmpty();
        }

        // Return true as long as there is at least one vertex that hasn't been visited yet.
        // This assumes 'vertices' contains all vertices in the graph and 'visited' contains
        // the set of vertices that have already been visited.
        if (vertices instanceof Collection) {
            return visited.size() < ((Collection<?>) vertices).size();
        } else if (vertices instanceof Map) {
            return visited.size() < ((Map<?, ?>) vertices).size();
        } else {
            // Fallback: if the type is unknown but is not empty, consider vertices unvisited
            return !vertices.isEmpty();
        }
    } catch (Exception e) {
        // In case of any unexpected error, assume no unvisited vertices remain
        return false;
    }
}

@Override
public boolean hasNext() {
    try {
        if (graph == null || visited == null) {
            return false;
        }
        // Some Graph implementations expose a getVertexCount() method; 
        // if not present, fall back to using getVertices().size().
        try {
            int total = graph.getVertexCount();
            return visited.size() < total;
        } catch (NoSuchMethodError | UnsupportedOperationException e) {
            // Fallback if getVertexCount() is not available
            int total = 0;
            for (Object v : graph.getVertices()) {
                total++;
            }
            return visited.size() < total;
        }
    } catch (Exception e) {
        // In case of any unexpected errors, conservatively report no more unvisited vertices.
        return false;
    }
}

