    if (path == null || path.isEmpty()){
        return null;
    }
    int lastDot = path.lastIndexOf('.');
    int lastSep = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // No dot after the last separator or dot is first character of the filename
    if (lastDot <= lastSep || lastDot <= lastSep + 1 || lastDot == path.length() - 1){
        return null;
    }
    return path.substring(0, lastDot);
}

