    if (length == 0) {
        return null;
    }

    // Find the last path separator (supports both '/' and '\\')
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDot = path.lastIndexOf('.');

    // No dot found, dot before the file name, or dot is the last character → no extension
    if (lastDot == -1 || lastDot <= lastSlash + 1 || lastDot == length - 1) {
        return null;
    }

