}

public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int len = path.length();
    // Find the last file separator
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // If path ends with a separator, there is no filename
    if (lastSlash == len - 1) {
        return null;
    }
    // Find the last dot
    int lastDot = path.lastIndexOf('.');
    // No dot at all or dot is part of directory name
    if (lastDot == -1 || lastDot <= lastSlash) {
        return null;
    }
    // Dot is the first character of the basename (no extension)
    if (lastDot == lastSlash + 1) {
        return null;
    }
    // Dot at the very end (empty extension), treat as no extension
    if (lastDot == len - 1) {
        return null;
    }
    return path.substring(0, lastDot);
}

