private String parseToken(final char[] terminators) {
    // Validate terminator array
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("Terminator array cannot be null or empty");
    }

    // If there is no source to read from, immediately return an empty token
    if (input == null) {
        return "";
    }

    StringBuilder token = new StringBuilder();
    int length = input.length();

    // Parse characters until a terminator is encountered or the input ends
    while (pos < length) {
        char current = input.charAt(pos);

        // Check if current character is one of the terminators
        boolean isTerminator = false;
        for (char term : terminators) {
            if (current == term) {
                isTerminator = true;
                break;
            }
        }

        // Stop if terminator reached
        if (isTerminator) {
            break;
        }

        // Append character to token and advance position
        token.append(current);
        pos++;
    }

    return token.toString();
