private String parseToken(final char[] terminators){
    // Return an empty token if the input source is not available.
    if (input == null) {
        return "";
    }

    StringBuilder token = new StringBuilder();

    // Loop until the end of the input or until one of the terminators is encountered.
    while (pos < input.length()) {
        char current = input.charAt(pos);

        // Check if the current character is a terminator.
        boolean isTerminator = false;
        if (terminators != null) {
            for (char term : terminators) {
                if (current == term) {
                    isTerminator = true;
                    break;
                }
            }
        }

        // If a terminator is found, stop parsing but do not consume the terminator.
        if (isTerminator) {
            break;
        }

        // Append the character to the token and advance the position.
        token.append(current);
        pos++;
    }

    return token.toString();
}

