private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Handle null input
    if (bounds == null) {
        return Pair.of(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    // Prepare the suffix list with the same size
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    long accumulator = 0L;

    // Compute suffix sums in reverse order
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException(\"Element at index \" + i + \" is null\");
        }
        accumulator += val;
        suffix.add((int) accumulator);
        total += val;
    }

    // Reverse to maintain the original order: suffix[i] corresponds to sum of bounds[i..n-1]
    Collections.reverse(suffix);
    return Pair.of(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffix = new ArrayList<>();
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(suffix, 0L);
    }
    long total = 0L;
    for (Integer b : bounds){
        if (b == null){
            throw new IllegalArgumentException("bounds contains null element");
        }
        total += b;
    }
    long currSum = 0L;
    for (int i = bounds.size() - 1; i >= 0; i--){
        currSum += bounds.get(i);
        suffix.add((int) currSum);
    }
    Collections.reverse(suffix);
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Handle null input gracefully
    if (bounds == null) {
        return new Pair<>(Collections.emptyList(), 0L);
    }

    int size = bounds.size();
    List<Integer> suffixList = new ArrayList<>(size);
    long totalSum = 0L;

    // Compute total sum of all elements
    for (Integer value : bounds) {
        if (value != null) {
            totalSum += value;
        }
    }

    // Compute suffix sums
    long suffixSum = 0L;
    int[] temp = new int[size];
    for (int i = size - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val != null) {
            suffixSum += val;
        } else {
            // Treat null as 0 for suffix sum computations
            // but keep it in the list as null to reflect original list's content
        }
        temp[i] = (int) suffixSum; // casting long to int (value may overflow but per spec)
    }

    // Build the result list preserving the original order
    for (int i = 0; i < size; i++) {
        suffixList.add(temp[i]);
    }

    return new Pair<>(suffixList, totalSum);
}

