    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int size = bounds.size();
    List<Integer> suffix = new ArrayList<>(size);
    long totalSum = 0L;
    for (int i = 0; i < size; i++) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list cannot contain null elements");
        }
        totalSum += val;
    }
    long suffixSum = 0L;
    for (int i = size - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffix.add((int) suffixSum); // cast to int as per required return type
    }
    Collections.reverse(suffix); // restore original order
    return new Pair<>(suffix, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null input by returning an empty result and sum of 0
    if (bounds == null) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffixList = new ArrayList<>(n);
    long totalSum = 0L;

    // Compute suffix sums from back to front
    // We store intermediate results in an array to avoid O(n^2) insertions
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        totalSum += val;
        temp[i] = (int) totalSum; // cast to int for the returned list
    }

    // Transfer to List<Integer>
    for (int i = 0; i < n; i++) {
        suffixList.add(temp[i]);
    }

