}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from > to) {
        throw new IllegalArgumentException("The 'from' index must be less than or equal to the 'to' index");
    }
    int length = arr.length;
    if (from < 0 || to >= length) {
        throw new IndexOutOfBoundsException("Indices are out of bounds. Array length: " + length);
    }
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    int length = arr.length;
    if (from < 0 || to >= length || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", array length=" + length);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        i++;
        j--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    // Guard against null array
    if (arr == null || arr.length == 0) {
        return;
    }
    // Clamp indices to legal range
    if (from < 0) {
        from = 0;
    }
    if (to >= arr.length) {
        to = arr.length - 1;
    }
    // If indices are out of order or no range to reverse, simply return
    if (from >= arr.length || to < 0 || from > to) {
        return;
    }
    // Perform the reversal in place
    int left = from;
    int right = to;
    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

