private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("Source list must not be null");
    }
    // If we are asked to move nodes from this list to itself or the list is empty,
    // nothing needs to be done.
    if (list == this || list.isEmpty()) {
        return;
    }
    // Transfer nodes one by one. We capture the next node before removing
    // the current node so that we can continue iterating safely.
    ListNodeImpl<E> current = list.firstNode;
    while (current != null) {
        ListNodeImpl<E> next = current.next;
        // Remove from the source list
        list.removeListNode(current);
        // Add to this list
        this.addListNode(current);
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to move
    }

    // Traverse the source list and move each node
    ListNodeImpl<E> current = list.getFirstNode();
    while (current != null) {
        ListNodeImpl<E> next = current.getNext(); // save next node before removal

        // Remove from source list
        try {
            list.removeListNode(current);
        } catch (RuntimeException e) {
            // If removal fails, propagate the exception
            throw new RuntimeException("Failed to remove node from source list", e);
        }

        // Add to destination list
        try {
            this.addListNode(current);
        } catch (RuntimeException e) {
            // If addition fails, attempt to re-insert the node back into the source list
            try {
                list.addListNode(current);
            } catch (RuntimeException re) {
                // If reinsertion fails, the node might be lost; wrap both failures
                throw new RuntimeException("Failed to add node to destination and failed to restore original list", re);
            }
            throw new RuntimeException("Failed to add node to destination list", e);
        }

        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list == this) {
        return;
    }
    // collect all nodes from the source list
    java.util.List<ListNodeImpl<E>> nodes = new java.util.ArrayList<>();
    for (ListNodeImpl<E> node : list) {
        nodes.add(node);
    }
    try {
        // move each node from the source to this list
        for (ListNodeImpl<E> node : nodes) {
            list.removeListNode(node);
            this.addListNode(node);
        }
    } catch (RuntimeException e) {
        // attempt to roll back to original state
        for (ListNodeImpl<E> node : nodes) {
            try {
                list.addListNode(node);
            } catch (RuntimeException ignored) {
                // ignore failures during rollback
            }
        }
        throw e;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Handle null or identical list case
    if (list == null || list == this) {
        return;
    }
    // If the source list is empty, nothing to do
    if (list.size == 0) {
        return;
    }

    // Save the number of nodes being moved before we clear the source list
    final int movedSize = list.size;

    // Grab the source list's head and tail nodes
    final ListNodeImpl<E> srcFirst = list.first;
    final ListNodeImpl<E> srcLast = list.last;

    // Detach the entire source list
    list.first = null;
    list.last = null;
    list.size = 0;

    // Append the detatched nodes to this list
    if (this.first == null) {
        // Destination list is empty
        this.first = srcFirst;
        this.last = srcLast;
    } else {
        // Connect the two lists
        this.last.next = srcFirst;
        srcFirst.prev = this.last;
        this.last = srcLast;
    }

    // Update the size counter
    this.size += movedSize;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new NullPointerException("list");
    }
    // If moving from the same list or the source list is empty, nothing to do.
    if (list == this || list.head == null) {
        return;
    }
    // Move nodes one by one: remove from source and add to destination.
    // This preserves node order and ensures all internal links are updated correctly.
    while (list.head != null) {
        ListNodeImpl<E> node = list.head;      // Current first node of the source list
        list.removeListNode(node);             // Detach it from the source list
        this.addListNode(node);                // Append it to the target list
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If str is not null but prefix is null, it does not start with null
    if (prefix == null) {
        return false;
    }

    // Quick length check: a longer prefix cannot match
    if (prefix.length() > str.length()) {
        return false;
    }

    // Use regionMatches to allow optional case-insensitive comparison
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, treat as matching.
    if (str == null) {
        return prefix == null;
    }
    // At this point str is not null, so a null prefix does not match.
    if (prefix == null) {
        return false;
    }
    // Empty prefix is always a match.
    if (prefix.isEmpty()) {
        return true;
    }
    // If prefix is longer than str, it cannot match.
    if (prefix.length() > str.length()) {
        return false;
    }
    try {
        if (ignoreCase) {
            // regionMatches with ignoreCase set to true performs a case-insensitive match.
            return str.regionMatches(true, 0, prefix, 0, prefix.length());
        } else {
            return str.startsWith(prefix);
        }
    } catch (Exception e) {
        // Any unexpected exception results in a non-match.
        return false;
    }
}

