    if (prefix == null) {
        return false;
    }

    // Use case-insensitive comparison when requested
    if (ignoreCase) {
        // regionMatches is safe for length mismatches, returns false if prefix longer than str
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

