public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("buf cannot be null");
    }
    if (this.name == null) {
        // No name to abbreviate, nothing to append
        return;
    }
    if (nameStart < 0 || nameStart > this.name.length()) {
        throw new IndexOutOfBoundsException("nameStart (" + nameStart + ") is out of bounds for name length " + this.name.length());
    }
    // Append the part of the name starting at the specified offset
    buf.append(this.name.substring(nameStart));
}

public void abbreviate(final int nameStart,final StringBuffer buf){
    if(buf == null){
        throw new IllegalArgumentException("buf cannot be null");
    }
    if(nameStart < 0 || nameStart > buf.length()){
        throw new IndexOutOfBoundsException("nameStart out of bounds: " + nameStart);
    }
    // Use the remaining part of the buffer starting at nameStart
    String remaining = buf.substring(nameStart);
    // Split on periods to find individual name parts
    String[] parts = remaining.split("\\.");
    StringBuilder abbr = new StringBuilder();
    for (String part : parts) {
        if (!part.isEmpty()) {
            abbr.append(part.charAt(0));
        }
    }
    // Append the abbreviation to the original buffer
    buf.append(abbr);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        return;
    }
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start >= buf.length()) {
        return;
    }
    // Extract the substring from the specified start position
    String namePart = buf.substring(start);
    // Split the name by dot separators
    String[] parts = namePart.split("\\.");
    if (parts.length <= 1) {
        // Nothing to abbreviate (no dot found)
        return;
    }
    StringBuilder abbreviated = new StringBuilder();
    // Abbreviate all components except the last one
    for (int i = 0; i < parts.length - 1; i++) {
        if (!parts[i].isEmpty()) {
            // keep only the first character of this component
            abbreviated.append(parts[i].charAt(0));
        }
        abbreviated.append('.');
    }
    // Append the last component unchanged
    abbreviated.append(parts[parts.length - 1]);
    // Replace the original portion with the abbreviated form
    buf.replace(start, buf.length(), abbreviated.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    // Validate nameStart bounds
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart is out of bounds");
    }
    // If the name part is empty, nothing to abbreviate
    if (nameStart == buf.length()) {
        return;
    }
    try {
        // Extract the substring from the given start index
        String fullName = buf.substring(nameStart);
        if (fullName.isEmpty()) {
            return;
        }
        // Split into components based on common separators
        String[] parts = fullName.split("[\\.\\-\\_\\s]+");
        if (parts.length == 0) {
            return;
        }
        // Build abbreviation using the first character of each part
        StringBuilder abbrev = new StringBuilder();
        for (String part : parts) {
            if (!part.isEmpty()) {
                abbrev.append(part.charAt(0));
            }
        }
        if (abbrev.length() == 0) {
            return;
        }
        // Append a separator if the buffer is not empty, then the abbreviation
        if (buf.length() > 0) {
            buf.append('.');
        }
        buf.append(abbrev);
    } catch (StringIndexOutOfBoundsException e) {
        // In case of an unexpected index issue, log and ignore
        // (Assuming a logger exists; otherwise, just swallow)
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Validate the buffer
    if (buf == null) {
        throw new IllegalArgumentException("buf must not be null");
    }

    // Source name should be stored in an instance field named 'name'
    final String src = this.name; // Assume this field exists in the enclosing class

    // If there is no name or nothing to abbreviate, just return
    if (src == null || src.isEmpty() || nameStart < 0 || nameStart >= src.length()) {
        return;
    }

    // Append abbreviated form to the buffer.
    // The algorithm keeps the first character of each component separated by '.' '/' '$' or '-'
    boolean takeNext = true;
    for (int i = nameStart; i < src.length(); i++) {
        char c = src.charAt(i);
        if (c == '.' || c == '/' || c == '$' || c == '-') {
            buf.append(c);
            takeNext = true;   // next non‑delimiter character is taken
        } else if (takeNext) {
            buf.append(c);
            takeNext = false;
        } // otherwise skip the character
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    try {
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        for (Type bound : bounds) {
            if (bound == null) {
                continue;
            }
            if (bound instanceof Class<?> && ((Class<?>) bound) == Object.class) {
                // skip default Object bound
                continue;
            }
            return bound;
        }
        // If all bounds are Object or none found
        return Unknown.class;
    } catch (Throwable t) {
        // In case of reflection errors, return Unknown
        return Unknown.class;
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds != null && bounds.length > 0) {
            return bounds[0];
        }
    } catch (Exception ignored) {
        // In case of any reflection issue, fall back to Unknown
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null) {
        return Unknown.class;
    }
    try {
        Type[] bounds = typeVariable.getBounds();
        if (bounds != null && bounds.length > 0) {
            Type bound = bounds[0];
            if (bound != null) {
                return bound;
            }
        }
    } catch (Exception ignored) {
        // ignore and fall through to return Unknown
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    if (typeVariable == null) {
        throw new IllegalArgumentException("typeVariable must not be null");
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds != null) {
        for (Type bound : bounds) {
            if (bound == null) {
                continue;
            }
            // Prefer concrete Class bounds that are not Object
            if (bound instanceof Class<?>) {
                Class<?> cls = (Class<?>) bound;
                if (cls != Object.class) {
                    return cls;
                }
            }
            // Handle parameterized types by returning their raw type if it is a Class
            if (bound instanceof ParameterizedType) {
                Type raw = ((ParameterizedType) bound).getRawType();
                if (raw instanceof Class<?>) {
                    return raw;
                }
            }
            // Handle generic array types by deriving the array class
            if (bound instanceof GenericArrayType) {
                Type component = ((GenericArrayType) bound).getGenericComponentType();
                if (component instanceof Class<?>) {
                    Class<?> componentCls = (Class<?>) component;
                    try {
                        // Create an empty array instance to obtain its class
                        return java.lang.reflect.Array.newInstance(componentCls, 0).getClass();
                    } catch (IllegalArgumentException e) {
                        // Fall back to Unknown if array creation fails
                    }
                }
            }
            // If the bound itself is a type variable, attempt to resolve it recursively
            if (bound instanceof TypeVariable<?>) {
                Type inner = resolveBound((TypeVariable<?>) bound);
                if (inner instanceof Class<?>) {
                    return inner;
                }
            }
        }
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        Type first = bounds[0];
        if (first instanceof Class<?> && Object.class.equals(first)) {
            return Unknown.class;
        }
        return first;
    } catch (Exception e) {
        // If any unexpected exception occurs, return Unknown.class as fallback.
        return Unknown.class;
    }
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("vertices must not be null");
    }

    int size = vertices.size();
    // An empty set or a single vertex is trivially a clique
    if (size <= 1) {
        return true;
    }

    // All vertices must belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }

    // Check all unordered pairs of vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                // For undirected graphs a single edge check is enough.  
                // For directed graphs, if either direction exists, we consider it sufficient;
                // this behaviour is conservative and prevents false positives.
                if (!graph.containsEdge(v1, v2) && !graph.containsEdge(v2, v1)) {
                    return false;
                }
            }
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }

    int size = vertices.size();
    if (size <= 1) {
        return true;
    }

    // Verify all vertices exist in the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }

    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V u = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V w = list.get(j);
            try {
                if (!graph.containsEdge(u, w)) {
                    return false;
                }
            } catch (Exception ex) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    // Handle null inputs
    if (graph == null || vertices == null) {
        return false;
    }
    // An empty graph or a singleton set is trivially a clique
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }
    // Convert set to array for efficient indexed access
    V[] arr = (V[]) new Object[size];
    int idx = 0;
    for (V v : vertices) {
        arr[idx++] = v;
    }
    // Check every pair of vertices for an edge
    for (int i = 0; i < size; i++) {
        V v1 = arr[i];
        for (int j = i + 1; j < size; j++) {
            V v2 = arr[j];
            // For undirected graphs, containsEdge handles both directions
            if (!graph.containsEdge(v1, v2) && !graph.containsEdge(v2, v1)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("graph and vertices must not be null");
    }
    int n = vertices.size();
    if (n < 2) {
        return true; // empty or single vertex is trivially a clique
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < n - 1; i++) {
        V vi = list.get(i);
        if (!graph.containsVertex(vi)) {
            return false;
        }
        for (int j = i + 1; j < n; j++) {
            V vj = list.get(j);
            if (!graph.containsVertex(vj)) {
                return false;
            }
            // For undirected graphs containsEdge(v1,v2) is sufficient;
            // for directed graphs we require an edge in either direction.
            boolean edgeExists = graph.containsEdge(vi, vj);
            if (!edgeExists) {
                edgeExists = graph.containsEdge(vj, vi);
            }
            if (!edgeExists) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    V[] verts = (V[]) vertices.toArray(new Object[0]);
    try {
        for (int i = 0; i < size; i++) {
            V v1 = verts[i];
            for (int j = i + 1; j < size; j++) {
                V v2 = verts[j];
                // Check for an edge in either direction
                if (!graph.containsEdge(v1, v2) && !graph.containsEdge(v2, v1)) {
                    return false;
                }
            }
        }
        return true;
    } catch (Exception e) {
        // In case of any runtime issue (e.g., vertices not part of graph), assume not a clique
        return false;
    }
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return result;
    }
    // Copy and sort keys using natural ordering
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort(new Comparator<>() {
        @Override
        public int compare(K o1, K o2) {
            if (o1 == null || o2 == null) {
                throw new IllegalArgumentException("Key cannot be null");
            }
            try {
                return ((Comparable) o1).compareTo(o2);
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Key does not implement Comparable", e);
            }
        }
    });
    // Compute lower bound for each key
    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        int lo = 0;
        int hi = sorted.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            K midVal = sorted.get(mid);
            int cmp;
            try {
                cmp = ((Comparable) midVal).compareTo(key);
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Key does not implement Comparable", e);
            }
            if (cmp < 0) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        int lowerIndex = lo - 1;
        result.add(lowerIndex >= 0 ? lowerIndex : -1);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }
    for (K key : keys) {
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("Key must be an Integer: " + key);
        }
        int primary = (Integer) key;
        Integer bestLower = null;
        for (K other : keys) {
            if (other == null) {
                continue;
            }
            if (other.equals(key)) { // skip the same key
                continue;
            }
            if (!(other instanceof Integer)) {
                continue;
            }
            int otherVal = (Integer) other;
            if (otherVal < primary) {
                if (bestLower == null || otherVal > bestLower) {
                    bestLower = otherVal;
                }
            }
        }
        lowerBounds.add(bestLower);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    for (K key : keys){
        if (key == null){
            result.add(null);
            continue;
        }
        Integer lower = null;
        for (K other : keys){
            if (other == null || other == key){
                continue;
            }
            try {
                @SuppressWarnings("unchecked")
                Comparable<? super K> comp = (Comparable<? super K>) other;
                if (comp.compareTo(key) < 0){
                    if (lower == null){
                        lower = (Integer) other;
                    } else {
                        try {
                            @SuppressWarnings("unchecked")
                            Comparable<? super Integer> lowerComp = (Comparable<? super Integer>) lower;
                            if (lowerComp.compareTo((Integer) other) < 0){
                                lower = (Integer) other;
                            }
                        } catch (ClassCastException e){
                            // ignore if lower is not an Integer
                        }
                    }
                }
            } catch (ClassCastException e){
                // If other is not Comparable, skip it
            }
        }
        result.add(lower);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    // Build a sorted set of integer keys (duplicates are ignored, but lower() works fine)
    TreeSet<Integer> sortedKeys = new TreeSet<>();
    for (K k : keys) {
        if (k == null) {
            continue;
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("Unsupported key type: " + k.getClass());
        }
        sortedKeys.add((Integer) k);
    }
    // For each key, find the maximum lower bound (previous element in sorted set)
    for (K k : keys) {
        if (k == null) {
            bounds.add(null);
            continue;
        }
        Integer keyVal = (Integer) k;
        Integer lower = sortedKeys.lower(keyVal);
        bounds.add(lower);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    TreeSet<K> seen = new TreeSet<>();
    for (K key : keys) {
        if (key == null) {
            result.add(null);
        } else {
            try {
                K lower = seen.lower(key);
                if (lower != null && lower instanceof Integer) {
                    result.add((Integer) lower);
                } else {
                    result.add(null);
                }
            } catch (ClassCastException e) {
                result.add(null);
            }
        }
        try {
            seen.add(key);
        } catch (ClassCastException e) {
            // If key cannot be added to the TreeSet, skip it for future lower checks
        }
    }
    return result;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor must not be null");
    }

    String types = descriptor;
    int idx = descriptor.indexOf('(');
    if (idx != -1) { // method descriptor
        int end = descriptor.indexOf(')', idx);
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        types = descriptor.substring(idx + 1, end);
    }

    int pos = 0;
    final int len = types.length();
    while (pos < len) {
        char c = types.charAt(pos);
        if (c == 'L') { // object
            int endSemicol = types.indexOf(';', pos);
            if (endSemicol == -1) {
                throw new IllegalArgumentException("Invalid descriptor: " + types);
            }
            pos = endSemicol + 1;
            output.pop(); // object types occupy one slot
        } else if (c == '[') { // array
            // consume all '['
            while (pos < len && types.charAt(pos) == '[') {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + types);
            }
            // now base type
            if (types.charAt(pos) == 'L') {
                int endSemicol = types.indexOf(';', pos);
                if (endSemicol == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: " + types);
                }
                pos = endSemicol + 1;
            } else {
                pos++; // primitive base
            }
            output.pop(); // arrays occupy one slot regardless of element type
        } else { // primitive or void
            switch (c) {
                case 'J': // long
                case 'D': // double
                    output.pop();
                    output.pop(); // long and double occupy two slots
                    break;
                case 'V': // void - nothing to pop
                    break;
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    output.pop(); // all other primitives occupy one slot
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor char: " + c);
            }
            pos++;
        }
    }
}

