    }
    List<Integer> bounds = new ArrayList<>();
    for (K key : keys){
        if (key == null){
            bounds.add(0);
            continue;
        }
        if (key instanceof Integer){
            bounds.add((Integer) key);
        } else {
            try{
                bounds.add(Integer.parseInt(key.toString()));
            }catch (NumberFormatException e){
                bounds.add(0);
            }
        }
    }
    return bounds;
}

