private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        int bound = 0;
        if (key instanceof Integer) {
            bound = ((Integer) key) + 1; // simple upper bound for integer keys
        } else if (key instanceof Number) {
            bound = ((Number) key).intValue() + 1;
        } else if (key instanceof CharSequence) {
            bound = ((CharSequence) key).length() + 1;
        } else {
            // Fallback: use hash code as a pseudo upper bound
            bound = key.hashCode();
        }
        bounds.add(bound);
    }
    return bounds;
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }
    try {
        // Percent-encode '{' as %7B and '}' as %7D
        return s.replace("{", "%7B").replace("}", "%7D");
    } catch (Exception e) {
        // In the unlikely event of an unexpected error, return the original string
        return s;
    }
}

public static String encodeTemplateNames(String s){
