    }
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

