public static boolean equals(Point2D p1, Point2D p2){
    // Handle reference equality and nulls
    if (p1 == p2) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    // Use a tolerance for floating-point comparison
    final double tolerance = 1e-9;
    double dx = p1.getX() - p2.getX();
    double dy = p1.getY() - p2.getY();
    return Math.abs(dx) <= tolerance && Math.abs(dy) <= tolerance;
}

public static boolean equals(Point2D p1, Point2D p2) {
    final double TOLERANCE = 1e-9;
    // Handle nulls
    if (p1 == null && p2 == null) return true;
    if (p1 == null || p2 == null) return false;

    // Handle NaN or infinite values
    double x1 = p1.getX();
    double y1 = p1.getY();
    double x2 = p2.getX();
    double y2 = p2.getY();

    if (Double.isNaN(x1) || Double.isNaN(y1) || Double.isNaN(x2) || Double.isNaN(y2))
        return false;
    if (!Double.isFinite(x1) || !Double.isFinite(y1) || !Double.isFinite(x2) || !Double.isFinite(y2))
        return false;

    return Math.abs(x1 - x2) <= TOLERANCE && Math.abs(y1 - y2) <= TOLERANCE;
}

public static boolean equals(Point2D p1, Point2D p2){
    // Handle null references
    if (p1 == null && p2 == null) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }

    final double tolerance = 1e-9;
    double dx = Math.abs(p1.getX() - p2.getX());
    double dy = Math.abs(p1.getY() - p2.getY());

    return dx <= tolerance && dy <= tolerance;
}

public static boolean equals(Point2D p1, Point2D p2) {
    final double tolerance = 1e-9;
    // Handle nulls
    if (p1 == p2) {
        return true; // covers both null
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    try {
        double dx = p1.getX() - p2.getX();
        double dy = p1.getY() - p2.getY();
        double distSq = dx * dx + dy * dy;
        return distSq <= tolerance * tolerance;
    } catch (Exception e) {
        // If any exception occurs (e.g., getX/getY problems), treat points as not equal
        return false;
    }
}

public static boolean equals(Point2D p1, Point2D p2) {
    try {
        if (p1 == p2) return true; // handles both null or same instance
        if (p1 == null || p2 == null) return false;
        double tolerance = 1e-9;
        return Math.abs(p1.getX() - p2.getX()) <= tolerance
                && Math.abs(p1.getY() - p2.getY()) <= tolerance;
    } catch (Exception e) {
        return false;
    }
}

