public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    path = path.trim();
    relativePath = relativePath.trim();

    // Determine if the base path is absolute (starts with '/')
    boolean isAbsolute = path.startsWith("/");

    // Use a list as a stack to store path segments
    java.util.List<String> stack = new java.util.ArrayList<>();

    // Tokenize the base path
    java.util.StringTokenizer st = new java.util.StringTokenizer(path, "/");
    while (st.hasMoreTokens()) {
        String token = st.nextToken();
        if (token.isEmpty() || token.equals(".")) {
            continue;
        } else if (token.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
            // ignore if stack is empty (cannot go above root)
        } else {
            stack.add(token);
        }
    }

    // Tokenize the relative path
    st = new java.util.StringTokenizer(relativePath, "/");
    while (st.hasMoreTokens()) {
        String token = st.nextToken();
        if (token.isEmpty() || token.equals(".")) {
            continue;
        } else if (token.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
            // ignore if stack is empty
        } else {
            stack.add(token);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // If we ended up with an empty path and it was absolute, return root '/'
    if (result.length() == 0 && isAbsolute) {
        return "/";
    }

    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    boolean leadingSlash = path.startsWith("/");
    java.util.ArrayList<String> baseSegments = new java.util.ArrayList<>();
    int i = 0;
    while (i < path.length()) {
        int slash = path.indexOf('/', i);
        if (slash == -1) {
            String part = path.substring(i);
            if (!part.isEmpty()) {
                baseSegments.add(part);
            }
            break;
        }
        if (slash > i) {
            String part = path.substring(i, slash);
            if (!part.isEmpty()) {
                baseSegments.add(part);
            }
        }
        i = slash + 1;
    }
    int j = 0;
    while (j < relativePath.length()) {
        int slash = relativePath.indexOf('/', j);
        String part;
        if (slash == -1) {
            part = relativePath.substring(j);
            j = relativePath.length();
        } else {
            part = relativePath.substring(j, slash);
            j = slash + 1;
        }
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!baseSegments.isEmpty()) {
                baseSegments.remove(baseSegments.size() - 1);
            }
        } else {
            baseSegments.add(part);
        }
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    if (leadingSlash) {
        sb.append('/');
    }
    for (int k = 0; k < baseSegments.size(); k++) {
        sb.append(baseSegments.get(k));
        if (k < baseSegments.size() - 1) {
            sb.append('/');
        }
    }
    return sb.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    try {
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path resolved = base.resolve(relativePath).normalize();
        String result = resolved.toString().replace('\\', '/');
        return result;
    } catch (Exception e) {
        throw new IllegalArgumentException("Error applying relative path: " + e.getMessage(), e);
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath cannot be null");
    }

    // Determine the base directory (excluding the last file component if path is a file)
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        baseDir = (lastSlash >= 0) ? path.substring(0, lastSlash + 1) : "";
    }

    // Use a deque to represent the current directory components
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    boolean isRoot = baseDir.startsWith("/");
    // Split the base directory into components ignoring empty parts
    for (String part : baseDir.split("/")) {
        if (!part.isEmpty()) {
            stack.addLast(part);
        }
    }

    // Process each component from the relative path
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!isRoot) {
                // If not rooted and we are at the top level, stay as is
                // (cannot go above the current relative base)
            }
        } else {
            stack.addLast(part);
        }
    }

    // Reconstruct the resulting path
    StringBuilder result = new StringBuilder();
    if (isRoot) {
        result.append("/");
    }
    boolean first = true;
    for (String comp : stack) {
        if (!first) {
            result.append("/");
        }
        result.append(comp);
        first = false;
    }

    // Handle case where the result is just the root
    if (result.length() == 0 && isRoot) {
        result.append("/");
    }

