}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return null;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // If the relative path is actually absolute, ignore the base path.
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] baseSegments = path.split("/");
    String[] relativeSegments = relativePath.split("/");

    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Push base path segments (ignore empty and "." segments)
    for (String seg : baseSegments) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        stack.addLast(seg);
    }

    // Apply relative segments
    for (String seg : relativeSegments) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            } else if (!isAbsolute) {
                // If the relative path goes above a relative base, keep ".." segments
                stack.addLast("..");
            }
            // If absolute and stack is empty, we simply ignore additional ".."
        } else {
            stack.addLast(seg);
        }
    }

    // Reconstruct the final path
    if (isAbsolute) {
        // Start with root "/"
        return "/" + String.join("/", stack);
    }
    // Relative path (no leading slash)
    return String.join("/", stack);
}

