    if (array == null) {
        return null;
    }

    boolean containsNull = false;
    for (Object obj : array) {
        if (obj == null) {
            containsNull = true;
            break;
        }
    }

    // If the array contains no nulls, we can safely cast it to String[].
    if (!containsNull) {
        // The caller is expected to pass a String[] instance.
        // If not, a ClassCastException may be thrown.
        return (String[]) array;
    }

    // Count non-null elements to determine the size of the new array.
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }

    // Create a new array and copy non-null elements.
    String[] result = new String[count];
    int index = 0;
    for (Object obj : array) {
        if (obj != null) {
            try {
                result[index++] = (String) obj;
            } catch (ClassCastException e) {
                // Throw a more descriptive exception for invalid element types.
                throw new IllegalArgumentException("Element is not a String: " + obj, e);
            }
        }
    }

    return result;
}

