    }
    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    // Find the last dot
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    // Find the last path separator (works for both Unix and Windows)
    int sepIndex = indexOfLastSeparator(filename);
    // If the last dot occurs before or at the last separator, it's not an extension
    if (dotIndex <= sepIndex) {
        return -1;
    }
    // If the dot is the first character after the last separator, it's a hidden file
    if (dotIndex == sepIndex + 1) {
        return -1;
    }
    return dotIndex;
}

