    int lastDot = filename.lastIndexOf('.');

    // If no dot exists, there is no extension
    if (lastDot == -1) {
        return -1;
    }

    // Determine the position of the last path separator (handles both Unix and Windows)
    int lastSeparator = indexOfLastSeparator(filename);

    // If a separator appears after the last dot, the dot cannot denote an extension
    if (lastSeparator > lastDot) {
        return -1;
    }

    // Otherwise, the last dot denotes the start of the extension
    return lastDot;
}

