public boolean isExpired(long timestamp, long expiredThreshold) {
    // Handle negative threshold values: treat as no expiration
    if (expiredThreshold < 0) {
        return false;
    }
    long now;
    try {
        now = System.currentTimeMillis();
    } catch (Exception e) {
        // If system time retrieval fails, conservatively do not expire
        return false;
    }
    // If the timestamp is in the future, the metric is definitely not expired
    if (timestamp > now) {
        return false;
    }
    // Determine if the elapsed time since the timestamp exceeds the allowed threshold
    try {
        return (now - timestamp) > expiredThreshold;
    } catch (ArithmeticException e) {
        // In case of overflow, consider it not expired to avoid false positives
        return false;
    }
}

public boolean isExpired(long timestamp,long expiredThreshold){
    // Validate input parameters
    if (timestamp < 0 || expiredThreshold <= 0) {
        throw new IllegalArgumentException("timestamp must be non-negative and expiredThreshold must be positive");
    }
    long currentTime = System.currentTimeMillis();
    // If the given timestamp is in the future, it cannot be expired yet
    if (currentTime < timestamp) {
        return false;
    }
    long age = currentTime - timestamp;
    // If the age exceeds the threshold, it is considered expired
    return age > expiredThreshold;
}

