    // Validate threshold
    if (expiredThreshold <= 0) {
        return false;
    }
    try {
        long currentTime = System.currentTimeMillis();
        // If timestamp is in the future, consider it not expired
        if (timestamp > currentTime) {
            return false;
        }
        // Compute elapsed time and compare with threshold
        return (currentTime - timestamp) >= expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, conservatively decide not expired
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold){
    try {
        // An expired threshold of zero or negative implies no expiration
        if (expiredThreshold <= 0) {
            return false;
        }
        long currentTime = System.currentTimeMillis();
        // If the timestamp is in the future, it cannot be expired
        if (timestamp > currentTime) {
            return false;
        }
        // If the elapsed time exceeds the threshold, the metric should be removed
        return currentTime - timestamp > expiredThreshold;
    } catch (Exception e) {
        // In the event of any unexpected exception, err on the side of not expiring
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate input parameters
    if (timestamp < 0) {
        throw new IllegalArgumentException("timestamp cannot be negative");
    }
    if (expiredThreshold <= 0) {
        // A non‑positive threshold means the entry never expires
        return false;
    }

    // Current time in milliseconds
    long currentTime;
    try {
        currentTime = System.currentTimeMillis();
    } catch (Exception e) {
        // In unlikely event of a system clock failure, do not consider it expired
        return false;
    }

    // If timestamp is in the future, it cannot be considered expired
    if (timestamp > currentTime) {
        return false;
    }

    // Compute elapsed time since the given timestamp
    long elapsed;
    try {
        elapsed = Math.subtractExact(currentTime, timestamp);
    } catch (ArithmeticException e) {
        // Overflow occurred; in this context, treat it as not expired
        return false;
    }

    // If elapsed time exceeds the threshold, it is expired
    return elapsed > expiredThreshold;
}

