protected void append(LoggingEvent event) {
    // Null check for the event itself
    if (event == null) {
        return;
    }

    // Extract the message from the event.
    // Assuming LoggingEvent exposes a getMessage() that returns a String.
    String message = event.getMessage();
    if (message == null) {
        return;
    }

    // Writing the message to each connected client.
    // It is assumed that there is a collection named 'clients' that holds objects
    // with a write(String) method capable of throwing IOException.
    synchronized (clients) {
        for (Client client : clients) {
            try {
                client.write(message);
            } catch (IOException e) {
                // Log the error to standard error. In a real implementation you might
                // delegate to an error handler or a logger.
                System.err.println("Failed to write log event to client: " + e.getMessage());
            } catch (Exception e) {
                // Catch any other unexpected exceptions so that one bad client
                // does not prevent other clients from receiving the log.
                System.err.println("Unexpected error while writing to client: " + e.getMessage());
            }
        }
    }
}

protected void append(LoggingEvent event) {
    // Guard against null events
    if (event == null) {
        return;
    }

    // Extract the formatted log message
    String message = event.getRenderedMessage();
    if (message == null) {
        message = "";
    }

    // Loop over the currently connected clients, sending the message.
    // The `clients` collection is assumed to be a thread‑safe set of Socket
    // objects (or any objects that provide an OutputStream).
    // Clients that throw an IOException are removed from the set.
    synchronized (clients) {
        Iterator<?> it = clients.iterator();
        while (it.hasNext()) {
            Object clientObj = it.next();
            try {
                // The client is expected to be a Socket; if it is not,
                // attempt to resolve an OutputStream through reflection
                if (clientObj instanceof java.net.Socket) {
                    java.net.Socket client = (java.net.Socket) clientObj;
                    java.io.PrintWriter out = new java.io.PrintWriter(
                        client.getOutputStream(), true);
                    out.println(message);
                } else {
                    // Fallback: try to find a writable OutputStream field
                    java.lang.reflect.Field outField = clientObj.getClass()
                        .getDeclaredField("outputStream");
                    outField.setAccessible(true);
                    java.io.OutputStream os = (java.io.OutputStream) outField.get(clientObj);
                    java.io.PrintWriter out = new java.io.PrintWriter(os, true);
                    out.println(message);
                }
            } catch (Exception ex) {
                // If the client cannot receive data, remove it
                it.remove();
            }
        }
    }
}

protected void append(LoggingEvent event){
    // Do nothing if there's no event
    if (event == null) {
        return;
    }

    // Extract the message from the event, handling any unexpected exceptions
    String message;
    try {
        message = event.getRenderedMessage();
    } catch (Exception e) {
        // Fallback to the event's string representation if anything goes wrong
        message = event.toString();
    }

    // Ensure message is not null to avoid NPEs later
    if (message == null) {
        message = "null";
    }

    // If there are no connected clients, exit early
    if (writers == null || writers.isEmpty()) {
        return;
    }

    // Iterate over all connected clients and send the message
    for (PrintWriter writer : writers) {
        if (writer == null) {
            continue; // Skip any null writers
        }
        try {
            writer.println(message);
            writer.flush();
        } catch (Exception e) {
            // If an exception occurs (e.g., client disconnected), log locally and skip
            // The actual logger may be this appender itself or another logger
            // For safety, we just ignore it in this implementation
            // Optionally, one could add the writer to a list of failed writers to remove later
        }
    }
}

