public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // EOF reached before any byte was read
            if (shift == 0) {
                return 0;
            }
            // EOF in the middle of a varint indicates a truncated tag
            throw new IOException("Truncated message while reading tag");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Tag is too long.");
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            // EOF before any byte was read -> normal end of stream
            if (shift == 0) {
                return 0;
            }
            // EOF during a multi-byte varint -> malformed input
            throw new java.io.EOFException("EOF while reading varint tag");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift > 35) {
            throw new IOException("Malformed varint tag (too many bytes)");
        }
    }
    return result;
}

